# Category content for /resume-examples/{category}/ and /cover-letter-examples/{category}/.
# n name, i intro (what recruiters in this field check first), e employer types, h what to highlight, cl cover-letter sample opening paragraph.

CATEGORIES = {
    'information-technology': dict(n='Information Technology', i='IT recruiters scan for your tech stack, the size of what you built and proof that it worked. A project line with a clear result beats a long list of tools.', e=['Product companies', 'IT services firms', 'Global capability centres', 'Start-ups', 'Banks and fintech teams'], h=['Tech stack named in each project', 'Results with numbers (speed, users, uptime)', 'Links to code or live work'], cl='I am applying for the Software Engineer role on your payments team. Over the last 3 years I have built and run REST services in Java and Spring Boot, and I enjoy the part of the job where a slow or broken system becomes fast and reliable again.'),
    'engineering': dict(n='Engineering', i='Engineering recruiters look for the tools you use, the processes you know and your shop-floor or site exposure. Mention plants, products and standards by name.', e=['Manufacturing plants', 'Automotive suppliers', 'EPC and infrastructure firms', 'Design and engineering services', 'Public sector units'], h=['Software and standards (CAD, GD&T, safety)', 'Process improvements with results', 'Plant, site or product exposure'], cl='I am writing to apply for the Mechanical Engineer position at your plant. In 3 years of design and production support I have designed fixtures that cut setup time and led root cause analysis that closed repeat quality issues.'),
    'accounting-finance': dict(n='Accounting & Finance', i='Finance recruiters check accuracy, compliance knowledge and the tools you use. GST, TDS, reconciliation and closing experience should be easy to spot.', e=['CA firms', 'Corporate finance teams', 'Banks and NBFCs', 'Shared service centres', 'Start-ups'], h=['Compliance work (GST, TDS, audit)', 'Tools (Tally, ERP, Excel)', 'Accuracy and deadlines met'], cl='I am applying for the Accountant role in your finance team. I have 4 years of experience filing GST and TDS returns on time, closing books every month and supporting statutory audits without major observations.'),
    'sales': dict(n='Sales', i='Sales recruiters want numbers first: target achievement, deal size, new accounts and territory. Show consistency over many months, not one lucky deal.', e=['FMCG and consumer durables', 'SaaS and technology', 'Pharma and healthcare', 'Banking and insurance', 'Real estate'], h=['Target achievement in percent', 'New accounts or revenue added', 'Industry and territory'], cl='I am writing to apply for the Sales Executive role. In the last financial year I achieved 110% of my target and opened 35 new business accounts by following up steadily and understanding what each client needed.'),
    'marketing': dict(n='Marketing', i='Marketing recruiters look for channels you have run, budgets you have handled and the results you can prove. Name the metrics you moved.', e=['Brands and D2C companies', 'Agencies', 'E-commerce', 'SaaS', 'Media'], h=['Channels owned (SEO, ads, social, email)', 'Metrics improved', 'Budget handled'], cl='I am applying for the Digital Marketing Executive role. Over 2 years I have grown organic traffic for an e-commerce brand through on-page SEO and steady content, and managed monthly ad budgets with a focus on cost per lead.'),
    'human-resources': dict(n='Human Resources', i='HR recruiters check hiring volume, HR operations, compliance and the tools you use. Show that you can be trusted with people data.', e=['Corporates', 'IT and BPO companies', 'Staffing firms', 'Manufacturing', 'Start-ups'], h=['Hiring numbers and roles closed', 'HR operations and compliance', 'HRMS and ATS tools'], cl='I am writing to apply for the HR Executive role. In 3 years I have closed more than 60 positions a year and run onboarding for every new joiner, from documents to induction.'),
    'education': dict(n='Education', i='Schools and colleges check subjects, classes taught, board or university, qualifications and results. Activities and parent communication also matter.', e=['CBSE, ICSE and state board schools', 'Colleges and universities', 'Coaching institutes', 'EdTech companies', 'Government schools'], h=['Subjects and classes taught', 'Qualifications and eligibility tests', 'Student results and activities'], cl='I am applying for the post of Mathematics Teacher. For 5 years I have taught classes 6 to 10 in a CBSE school, using activity-based lessons to help weaker students catch up.'),
    'government': dict(n='Government', i='Government recruitment usually follows the official notification. For contract roles, PSUs and interviews, a clear resume with exact dates, qualifications and duties helps.', e=['Central government departments', 'State government departments', 'Public sector units', 'Public sector banks', 'Autonomous bodies'], h=['Exact qualifications and dates', 'Duties and responsibilities', 'Languages and computer skills'], cl='I am writing to apply for the contract post in your department. I have 2 years of experience in office administration, record keeping and data entry on government portals.'),
    'retail': dict(n='Retail', i='Retail recruiters look for customer service, sales targets, billing accuracy and shift flexibility. Store size and footfall help them picture your work.', e=['Fashion and lifestyle stores', 'Supermarkets', 'Electronics stores', 'Quick commerce', 'Malls'], h=['Sales targets met', 'Customer service and billing', 'Store type and footfall'], cl='I am applying for the Retail Sales Associate role. I have 2 years of experience on a busy fashion store floor, helping 50 or more customers a day and meeting my monthly targets in most months.'),
    'legal': dict(n='Legal', i='Legal recruiters check practice areas, courts or forums, drafting experience and the kind of clients you have served. Confidentiality matters, so describe matters in general terms.', e=['Law firms', 'Chambers of senior advocates', 'Corporate legal teams', 'Legal process outsourcing', 'Government legal departments'], h=['Practice areas', 'Drafting and court experience', 'Research skills'], cl='I am writing to apply for the Associate position in your litigation team. In 4 years of practice I have drafted pleadings in civil and commercial matters and appeared before district courts and tribunals.'),
    'maintenance-repair': dict(n='Maintenance & Repair', i='Maintenance recruiters look for your trade, machines handled, safety practice and breakdown records. Name the equipment you know.', e=['Factories', 'Facility management companies', 'Hospitals and hotels', 'Service centres', 'Builders'], h=['Trade and certificates', 'Machines and systems handled', 'Safety practice'], cl='I am applying for the Maintenance Technician role. I am an ITI Fitter with 5 years of experience in preventive and breakdown maintenance of CNC and textile machines.'),
    'administrative': dict(n='Administrative & Customer Support', i='Office and support roles are judged on reliability, accuracy, communication and computer skills. Typing speed, languages and tools should be easy to find.', e=['Corporate offices', 'BPO and customer support centres', 'Hospitals', 'Schools', 'Small businesses'], h=['Computer skills and typing speed', 'Languages', 'Volume handled (calls, records, tickets)'], cl='I am writing to apply for the Administrative Assistant role. For 4 years I have managed calendars, travel and records for senior managers, so that they could focus on their work.'),
    'real-estate': dict(n='Real Estate', i='Real estate recruiters look for units sold or managed, project types and local market knowledge. Honest dealing with buyers is valued.', e=['Developers', 'Brokerage firms', 'Property management companies', 'Co-working operators', 'Facility management firms'], h=['Units sold or properties managed', 'Project types', 'Local market knowledge'], cl='I am applying for the Sales Executive role for your residential projects. In 2 years I have closed the sale of more than 30 apartments by understanding buyer needs and following up patiently.'),
    'production': dict(n='Production & Manufacturing', i='Production recruiters check the industry, processes, output and quality results, and safety. Standards such as GMP or 5S should be visible.', e=['FMCG plants', 'Pharma manufacturing', 'Textile mills', 'Auto component makers', 'Chemical plants'], h=['Processes and equipment', 'Output and quality results', 'Standards (GMP, 5S, safety)'], cl='I am writing to apply for the Production Officer role. I have 4 years of experience in oral solid dosage manufacturing and I keep batch records right first time.'),
    'business-management': dict(n='Business & Management', i='Management recruiters look for the scope you handled (team, budget, products) and the outcomes you drove. Show decisions, not only duties.', e=['Corporates', 'Consulting firms', 'Start-ups', 'IT companies', 'Manufacturing'], h=['Scope: team, budget, products', 'Outcomes and metrics', 'Decisions you made'], cl='I am applying for the Product Manager role. For 4 years I have worked with engineering and design teams to ship features that solved real user problems and moved clear metrics.'),
    'security-protective-services': dict(n='Security & Protective Services', i='Security employers check training, alertness, discipline and the type of premises you have guarded. Ex-servicemen should mention service details.', e=['Security agencies', 'Corporate offices', 'Residential complexes', 'Malls and hospitals', 'Factories'], h=['Training and licence', 'Premises type and size', 'Incident handling'], cl='I am writing to apply for the Security Guard position. I have 5 years of experience guarding corporate offices and residential complexes and I keep every register complete.'),
    'hospitality-catering': dict(n='Hospitality & Catering', i='Hospitality recruiters check departments worked, property size, guest feedback and grooming. Industrial training details help freshers.', e=['Hotels and resorts', 'Restaurants and cafes', 'Cloud kitchens', 'Airlines and cruise lines', 'Event caterers'], h=['Departments and property type', 'Guest feedback and upselling', 'Cuisines or systems known'], cl='I am applying for the Front Office Executive role. For 3 years I have handled check-ins, guest requests and complaints at a 120-room hotel and helped improve our review scores.'),
    'transport-logistics': dict(n='Transport & Logistics', i='Logistics recruiters look for volumes handled, on-time delivery, inventory accuracy and the systems you use.', e=['3PL companies', 'E-commerce warehouses', 'Manufacturers', 'Freight forwarders', 'Retail chains'], h=['Shipments or SKUs handled', 'On-time and accuracy results', 'ERP or WMS used'], cl='I am writing to apply for the Logistics Executive role. I plan daily dispatches for more than 40 shipments and work closely with transporters to deliver on time.'),
    'transportation': dict(n='Transportation', i='Transport employers check licence type, years of driving, routes known and safety record.', e=['Logistics companies', 'E-commerce delivery', 'Corporate transport', 'Schools', 'Ride services'], h=['Licence type and validity', 'Years and routes', 'Safety record'], cl='I am applying for the Driver position. I have 8 years of commercial driving experience and a clean record on both city and highway routes.'),
    'medical': dict(n='Medical & Healthcare', i='Healthcare recruiters check registration, qualifications, departments worked, patient load and emergency skills. Certifications such as BLS should be clear.', e=['Multi-speciality hospitals', 'Clinics', 'Diagnostic labs', 'Pharmacies', 'Home-care providers'], h=['Registration and qualifications', 'Departments and patient load', 'Certifications (BLS, ACLS)'], cl='I am writing to apply for the Staff Nurse position. I hold a B.Sc in Nursing and have 4 years of experience in medical-surgical and ICU wards, with a strong focus on medication safety.'),
    'sport-fitness': dict(n='Sport & Fitness', i='Fitness employers look for certifications, client results and the kinds of training you run.', e=['Gyms and fitness studios', 'Corporate wellness', 'Sports academies', 'Hotels and clubs', 'Online coaching'], h=['Certifications', 'Client results', 'Classes and formats'], cl='I am applying for the Personal Trainer role. I am certified and have trained 25 personal clients with plans built around their goals and safety.'),
    'social-work': dict(n='Social Work & NGO', i='NGOs look for field experience, the communities you served, programmes managed and how you reported impact.', e=['NGOs', 'CSR foundations', 'Government programmes', 'International agencies', 'Social enterprises'], h=['Field experience and communities', 'Programmes and scale', 'Reporting and impact'], cl='I am writing to apply for the Programme Coordinator role. I have 5 years of experience running education projects across 30 schools and reporting to donors on time.'),
    'construction': dict(n='Construction', i='Construction recruiters check project types and size, site responsibilities, quality and safety records.', e=['Builders and developers', 'EPC contractors', 'Infrastructure firms', 'Interior contractors', 'Government projects'], h=['Project type and size', 'Site responsibilities', 'Safety and quality'], cl='I am applying for the Site Engineer role. For 4 years I have managed daily work on building and road projects, keeping quality checks and progress reports up to date.'),
    'beauty-wellness': dict(n='Beauty & Wellness', i='Salons and spas look for services offered, hygiene, client retention and a portfolio.', e=['Salons', 'Spas', 'Bridal studios', 'Home-service platforms', 'Hotels'], h=['Services and specialities', 'Hygiene practice', 'Portfolio and repeat clients'], cl='I am writing to apply for the Beautician role. I have 4 years of experience in skin care, threading, waxing and bridal make-up, and many of my clients return regularly.'),
    'student': dict(n='Students & Freshers', i='For freshers, recruiters read education, projects, internships and skills. Keep it to one page and show what you did, not only what you studied.', e=['Campus recruiters', 'Start-ups', 'IT services firms', 'Banks', 'Government and PSU exams'], h=['Education and scores', 'Projects and internships', 'Skills and certifications'], cl='I am a final-year B.Tech student applying for the Graduate Engineer Trainee role. My final-year project and a 2-month internship gave me practical experience that I want to build on in your team.'),
    'creative-artistic': dict(n='Creative & Design', i='Creative recruiters open your portfolio first. Your resume should point to it and name the brands, formats and tools you work with.', e=['Agencies', 'Brands and D2C companies', 'Media and production houses', 'Start-ups', 'Freelance clients'], h=['Portfolio link', 'Formats and tools', 'Results such as engagement or launches'], cl='I am applying for the Graphic Designer role. Over 3 years I have designed more than 300 social creatives and a full brand kit, and my portfolio link is in my resume.'),
}
